/* Player name tags drawn with the HUD API v2 (docs/mod-sdk-v2.md "Drawing on screen").
 *
 * The HUD text element has one built-in font and one colour, so the name is drawn from the
 * package's own glyph atlas (assets/name_fill.png, assets/name_outline.png, Cinzel under the SIL
 * Open Font License, generated by tools/multiplayer/make_name_font.py): every glyph is an image
 * element with its atlas UVs. A dark outline pass goes first; the fill is then drawn NAME_BANDS
 * times, each time inside a horizontal clip band (WWHD_HUD_CLIP_PUSH/POP) and tinted from white
 * at the top to grey at the bottom: a vertical gradient. A last fill pass lays the player's
 * primary tunic colour over it, half transparent. Every pass is multiplied by the caller's
 * opacity (the distance fade of mod.c). Elements per name: 2 * glyphs + NAME_BANDS * (glyphs
 * + 2), at most 104 for 16 letters, 832 for MAX_REMOTES names: under the 1024 of a HUD list.
 * Without the atlas (failed load), the built-in text element is used. */
#pragma once
#include "wwhd_guest.h"
#include "name_font.h"

#define NAME_BANDS 4
#define NAME_OUTLINE_RGBA 0x10141CD8u
#define NAME_TOP_RGB 0xFFFFFFu
#define NAME_BOTTOM_RGB 0x8C8C8Cu
#define NAME_OVERLAY_ALPHA 0.45f

static u32 name_fill_texture, name_outline_texture;
static unsigned long long name_texture_epoch = ~0ull;
static int name_textures_ok;
static int name_texture_failure_logged;
static wwhd_hud_element name_element;

/* The atlas handles, reloaded after a state load (wwhd_hud_epoch). */
static int name_textures_ready(void) {
    unsigned long long epoch = wwhd_hud_epoch();
    if (epoch != name_texture_epoch) {
        name_texture_epoch = epoch;
        name_fill_texture = wwhd_hud_texture(WWHD_HUD_PACKAGE, "assets/name_fill.png");
        name_outline_texture = wwhd_hud_texture(WWHD_HUD_PACKAGE, "assets/name_outline.png");
        name_textures_ok = name_fill_texture && name_outline_texture;
        if (!name_textures_ok && !name_texture_failure_logged) {
            name_texture_failure_logged = 1;
            wwhd_log("multiplayer: name font atlas not loaded, plain text used");
        }
    }
    return name_textures_ok;
}

static u32 name_mix(u32 a, u32 b, f32 t) { /* 0xRRGGBB channels */
    u32 out = 0;
    for (int shift = 16; shift >= 0; shift -= 8) {
        f32 ca = (f32)((a >> shift) & 0xFF), cb = (f32)((b >> shift) & 0xFF);
        u32 c = (u32)(ca + (cb - ca) * t + 0.5f);
        out |= (c > 255 ? 255u : c) << shift;
    }
    return out;
}

static f32 name_width(const char* text, u32 length, f32 scale) {
    f32 width = 0.0f;
    for (u32 i = 0; i != length; ++i) {
        u32 c = (u8)text[i];
        if (c < NAME_FONT_FIRST || c >= NAME_FONT_FIRST + NAME_FONT_COUNT) c = '?';
        width += name_font[c - NAME_FONT_FIRST].advance * scale;
    }
    return width;
}

static void name_glyphs(u32 list, u32 texture, const char* text, u32 length, f32 x, f32 baseline,
                        f32 scale, u32 rgba) {
    for (u32 i = 0; i != length; ++i) {
        u32 c = (u8)text[i];
        if (c < NAME_FONT_FIRST || c >= NAME_FONT_FIRST + NAME_FONT_COUNT) c = '?';
        const name_glyph* g = &name_font[c - NAME_FONT_FIRST];
        if (g->w > 8) { /* a cell of padding only: the space */
            name_element = (wwhd_hud_element){
                .kind = WWHD_HUD_IMAGE, .anchor = WWHD_HUD_CENTER, .blend = WWHD_HUD_ALPHA,
                .x = x + (f32)g->dx * scale, .y = baseline + (f32)g->dy * scale,
                .w = (f32)g->w * scale, .h = (f32)g->h * scale, .thickness = 1,
                .u0 = (f32)g->x / (f32)NAME_FONT_ATLAS_W, .v0 = (f32)g->y / (f32)NAME_FONT_ATLAS_H,
                .u1 = (f32)(g->x + g->w) / (f32)NAME_FONT_ATLAS_W,
                .v1 = (f32)(g->y + g->h) / (f32)NAME_FONT_ATLAS_H,
                .rgba = rgba, .image = texture};
            wwhd_hud_emit(list, &name_element);
        }
        x += g->advance * scale;
    }
}

static void name_clip(u32 list, u32 kind, f32 x, f32 y, f32 w, f32 h) {
    name_element = (wwhd_hud_element){.kind = kind, .anchor = WWHD_HUD_CENTER, .x = x, .y = y,
                                      .w = w, .h = h, .thickness = 1, .u1 = 1, .v1 = 1};
    wwhd_hud_clip(list, &name_element);
}

/* 0xRRGGBB with an alpha of a * opacity. */
static u32 name_rgba(u32 rgb, f32 a, f32 opacity) {
    u32 alpha = (u32)(a * opacity * 255.0f + 0.5f);
    return (rgb << 8) | (alpha > 255 ? 255u : alpha);
}

/* Draws text centred on cx with its baseline at y; scale 1 = NAME_FONT_SIZE pixels, opacity in
 * (0, 1]. */
static void name_draw(u32 list, f32 cx, f32 baseline, const char* text, u32 length, u32 primary_rgb,
                      f32 scale, f32 opacity) {
    if (!length || !(opacity > 0.0f)) return;
    if (opacity > 1.0f) opacity = 1.0f;
    f32 width = name_width(text, length, scale);
    f32 x = cx - width * 0.5f;
    if (!name_textures_ready()) {
        name_element = (wwhd_hud_element){.kind = WWHD_HUD_TEXT, .anchor = WWHD_HUD_CENTER,
                                          .x = x, .y = baseline - (f32)NAME_FONT_CAP * scale,
                                          .size = (f32)NAME_FONT_CAP * scale * 1.3f, .thickness = 1,
                                          .u1 = 1, .v1 = 1,
                                          .rgba = name_rgba(name_mix(NAME_TOP_RGB, primary_rgb, NAME_OVERLAY_ALPHA), 1.0f, opacity),
                                          .text = text, .text_bytes = length};
        wwhd_hud_emit(list, &name_element);
        return;
    }
    name_glyphs(list, name_outline_texture, text, length, x, baseline, scale,
                name_rgba(NAME_OUTLINE_RGBA >> 8, (f32)(NAME_OUTLINE_RGBA & 0xFF) / 255.0f, opacity));

    f32 cap_top = baseline - (f32)NAME_FONT_CAP * scale, band = ((f32)NAME_FONT_CAP * scale) / NAME_BANDS;
    f32 left = x - 8.0f * scale, span = width + 16.0f * scale;
    for (int i = 0; i != NAME_BANDS; ++i) {
        /* the first and last bands reach the tallest and lowest glyph cells */
        f32 y0 = i == 0 ? baseline + (f32)NAME_FONT_TOP * scale : cap_top + band * (f32)i;
        f32 y1 = i == NAME_BANDS - 1 ? baseline + (f32)NAME_FONT_BOTTOM * scale : cap_top + band * (f32)(i + 1);
        u32 rgb = name_mix(NAME_TOP_RGB, NAME_BOTTOM_RGB, (f32)i / (f32)(NAME_BANDS - 1));
        name_clip(list, WWHD_HUD_CLIP_PUSH, left, y0, span, y1 - y0);
        name_glyphs(list, name_fill_texture, text, length, x, baseline, scale, name_rgba(rgb, 1.0f, opacity));
        name_clip(list, WWHD_HUD_CLIP_POP, 0, 0, 0, 0);
    }
    name_glyphs(list, name_fill_texture, text, length, x, baseline, scale,
                name_rgba(primary_rgb, NAME_OVERLAY_ALPHA, opacity));
}
